import{_ as t,o as d,c as a,a2 as o}from"./chunks/framework.CT6jiXWi.js";const u=JSON.parse('{"title":"Features","description":"","frontmatter":{},"headers":[],"relativePath":"pipeline/reference/features.md","filePath":"pipeline/reference/features.md","lastUpdated":1783704404000}'),r={name:"pipeline/reference/features.md"};function c(s,e,i,n,l,h){return d(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h1><p>What <code>cds-data-pipeline</code> does, grouped by capability. Programmatic API reference is in <a href="./management-service.html">Management Service</a>; protocol-specific notes are in the <a href="./../guide/sources/odata.html">OData</a> and <a href="./../guide/sources/rest.html">REST</a> adapter pages.</p><h2 id="source-adapters" tabindex="-1">Source adapters <a class="header-anchor" href="#source-adapters" aria-label="Permalink to &quot;Source adapters&quot;">​</a></h2><p>The READ phase of every pipeline uses a protocol-specific adapter. The adapter is selected automatically from the remote service&#39;s <code>kind</code>; custom adapters extend <code>BaseSourceAdapter</code> and implement <code>readStream(tracker)</code>.</p><table tabindex="0"><thead><tr><th>Adapter</th><th>Protocol support</th><th>Reference</th></tr></thead><tbody><tr><td><strong>OData V4</strong></td><td>Batch reads with <code>$select</code> restriction, all three delta modes, <code>$top</code> / <code>$skip</code> pagination.</td><td><a href="./../guide/sources/odata.html">Sources → OData V2 / V4</a></td></tr><tr><td><strong>OData V2</strong></td><td>Same surface as V4, with V2 timestamp quirks handled. Provider needs <code>@cap-js-community/odata-v2-adapter</code>.</td><td><a href="./../guide/sources/odata.html">Sources → OData V2 / V4</a></td></tr><tr><td><strong>REST</strong></td><td>Cursor / offset / page pagination, configurable delta URL parameter, nested-response extraction via <code>dataPath</code>.</td><td><a href="./../guide/sources/rest.html">Sources → REST Adapter</a></td></tr><tr><td><strong>CQN</strong></td><td>Reads from CQN-native services (in-process CAP services, <code>cds.requires</code> DB bindings, CAP-wrapped legacy DBs). Serves both entity-shape (row-preserving) and query-shape (derived / aggregated snapshot) reads based on whether <code>source.query</code> is supplied.</td><td><a href="./../guide/sources/cqn.html">Sources → CQN Adapter</a></td></tr><tr><td><strong>Server-driven paging</strong></td><td>Adapters keep paging until the remote returns an empty batch — transparent to the replication config.</td><td>Applies to OData V4 and V2 adapters.</td></tr><tr><td><strong>Multi-source fan-in</strong></td><td>Consolidate the same logical entity from N backends into one target table via sibling pipelines, each stamping a <code>source.origin</code> label into a <code>source</code> key column contributed by the <code>plugin.data_pipeline.sourced</code> aspect. Per-origin <code>flush</code> and <code>mode: &#39;full&#39;</code> scope DELETEs to their own origin.</td><td><a href="./../guide/recipes/multi-source.html">Recipes → Multi-source</a></td></tr><tr><td><strong>Auto-selection + custom base class</strong></td><td>Selected automatically from the service&#39;s <code>kind</code>, or routed explicitly via <code>source.kind</code> / <code>source.adapter</code> class ref. Custom adapters extend <code>BaseSourceAdapter</code>.</td><td><a href="./../guide/sources/custom.html">Sources → Custom source adapter</a></td></tr></tbody></table><h2 id="target-adapters" tabindex="-1">Target adapters <a class="header-anchor" href="#target-adapters" aria-label="Permalink to &quot;Target adapters&quot;">​</a></h2><p>The WRITE phase (and pre-write truncate / delete-slice) is delegated to a <code>BaseTargetAdapter</code>. The adapter is resolved from <code>target.adapter</code> (class ref) or <code>target.service</code> (with <code>db</code> / unset → <code>DbTargetAdapter</code>).</p><table tabindex="0"><thead><tr><th>Adapter</th><th>Primitives</th><th>Reference</th></tr></thead><tbody><tr><td><strong><code>DbTargetAdapter</code></strong> (default)</td><td><code>UPSERT</code> / <code>INSERT</code> / <code>DELETE</code> via <code>cds.connect.to(&#39;db&#39;)</code>. Reports all four capabilities (<code>keyAddressableUpsert</code>, <code>truncate</code>, <code>batchDelete</code>, <code>batchInsert</code>).</td><td><a href="./../guide/targets/db.html">Targets → Local DB</a></td></tr><tr><td><strong><code>ODataTargetAdapter</code></strong></td><td>Resolved when <code>target.kind</code> is <code>&#39;odata&#39; / &#39;odata-v2&#39;</code>, or when the connected remote service advertises that kind. Routes <code>UPSERT</code> / <code>INSERT</code> through CAP&#39;s remote runtime (POST / PUT / PATCH, with <code>$batch</code> change sets where supported); <code>truncate</code> / <code>deleteSlice</code> page keys + issue per-row DELETE. Reports all four capabilities.</td><td><a href="./../guide/targets/odata.html">Targets → OData</a>, <a href="./../guide/recipes/built-in-replicate.html#to-a-remote-odata-target">Recipes → Built-in replicate</a></td></tr><tr><td><strong>Custom target adapter</strong></td><td>Pluggable class extending <code>BaseTargetAdapter</code> with <code>writeBatch</code>, <code>truncate</code>, <code>deleteSlice</code>, and <code>capabilities()</code>. Used for non-db, non-OData targets (message buses, custom HTTP APIs, …).</td><td><a href="./../guide/targets/custom.html">Targets → Custom target adapter</a>, <a href="./../guide/recipes/custom-target-adapter.html">Recipes → Custom target adapter</a></td></tr></tbody></table><h2 id="management-service" tabindex="-1">Management service <a class="header-anchor" href="#management-service" aria-label="Permalink to &quot;Management service&quot;">​</a></h2><p>An OData service for operating pipelines at runtime. See <a href="./management-service.html">Management Service</a>.</p><table tabindex="0"><thead><tr><th>Endpoint</th><th>What it does</th></tr></thead><tbody><tr><td><strong><code>Pipelines</code></strong></td><td>Read-only listing of all registered pipelines with source / target config, status, last sync, and statistics.</td></tr><tr><td><strong><code>PipelineRuns</code></strong></td><td>Per-run history with start / end timestamps, trigger, mode, statistics, and error details.</td></tr><tr><td><strong><code>execute</code> action</strong></td><td>Trigger a pipeline run programmatically or via unbound HTTP <code>POST /pipeline/execute</code>.</td></tr><tr><td><strong><code>start</code> action</strong></td><td>Bound to <code>Pipelines</code> — same run as <code>execute</code> with the pipeline name taken from the entity key (Fiori Elements object pages).</td></tr><tr><td><strong><code>flush</code> action</strong></td><td>Clear pipeline output and reset tracker for a named pipeline.</td></tr><tr><td><strong><code>status</code> function</strong></td><td>Get the current status of a named pipeline.</td></tr></tbody></table><h2 id="pipeline-console-ui" tabindex="-1">Pipeline Console UI <a class="header-anchor" href="#pipeline-console-ui" aria-label="Permalink to &quot;Pipeline Console UI&quot;">​</a></h2><p>Pre-built UI5 freestyle app shipped in the npm package (<code>app/pipeline-console/</code>). Enable locally with <code>management.reuse.console</code> in <code>cds.requires.datapipeline</code>, or own the UI on BTP with <code>cds add pipeline-console</code>. Full walkthrough: <a href="./../guide/pipeline-console.html">Pipeline Console</a> and <a href="./../guide/feature-activation.html">Feature activation</a>.</p><table tabindex="0"><thead><tr><th>Capability</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Config reuse</strong></td><td><code>management.reuse.console: true</code> serves static UI from the plugin package at <code>/pipeline-console/</code> — no local copy, no <code>server.js</code> changes.</td></tr><tr><td><strong>BTP scaffold</strong></td><td><code>cds add pipeline-console</code> copies UI into <code>app/pipeline-console/</code> with HTML5 deploy scaffolding.</td></tr><tr><td><strong>Same-origin OData</strong></td><td>Console binds to <code>/pipeline/</code> on the CAP server that serves the UI.</td></tr></tbody></table><h2 id="observability" tabindex="-1">Observability <a class="header-anchor" href="#observability" aria-label="Permalink to &quot;Observability&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Pipeline tracker</strong></td><td><code>Pipelines</code> table persists name, source, target, mode, <code>lastSync</code>, <code>lastKey</code>, and status per pipeline. Behaviour is inferred from config shape at registration — no stored discriminator (see <a href="./../guide/concepts/inference.html">Inference rules</a>).</td></tr><tr><td><strong>Run history</strong></td><td>Every run gets a <code>PipelineRuns</code> record with full context and timing.</td></tr><tr><td><strong>Statistics</strong></td><td><code>created</code> / <code>updated</code> / <code>deleted</code> / <code>skipped</code> counts per run and cumulative.</td></tr><tr><td><strong>Data inspector</strong></td><td>On-demand paged preview of source and target rows per pipeline (<code>inspectData</code>), plus per-pipeline data-flow and landscape metadata. Powers the <a href="./../guide/pipeline-console.html">Pipeline Console</a>.</td></tr></tbody></table><h2 id="scheduling-and-triggers" tabindex="-1">Scheduling and triggers <a class="header-anchor" href="#scheduling-and-triggers" aria-label="Permalink to &quot;Scheduling and triggers&quot;">​</a></h2><p>Three ways to drive a pipeline. Pick the one that matches your operational model — they can be mixed across pipelines in the same app.</p><table tabindex="0"><thead><tr><th>Capability</th><th>What it does</th><th>When to pick it</th></tr></thead><tbody><tr><td><strong>In-process <code>spawn</code> scheduling</strong> (default)</td><td>Periodic runs driven by <code>cds.spawn({ every })</code>. <code>schedule: 600000</code> or <code>schedule: { every, engine: &#39;spawn&#39; }</code>. Best-effort; fires on every app instance.</td><td>Single-instance deployments, dev, best-effort cadence.</td></tr><tr><td><strong>In-process <code>queued</code> scheduling</strong></td><td>Persistent task queue via <code>cds.queued(srv).schedule(...).every(...)</code>. <code>schedule: { every: &#39;10m&#39;, engine: &#39;queued&#39; }</code>. Single-winner across app instances, survives restarts, retries with exponential backoff. Requires <code>cds.outbox.Messages</code>; underlying CAP API is experimental.</td><td>Self-contained CAP apps running with &gt;1 instance that want persistence and cross-instance safety. See <a href="./../guide/recipes/internal-scheduling-queued.html">Recipes → Internal scheduling with the queued engine</a>.</td></tr><tr><td><strong>External trigger</strong></td><td>Omit <code>schedule</code> entirely and call <code>POST /pipeline/execute</code> from an external scheduler (SAP BTP Job Scheduling Service, Kubernetes <code>CronJob</code>, ...). The <code>execute</code> action accepts <code>trigger</code> and <code>async</code> parameters for correct attribution and fire-and-forget 202 responses.</td><td>Centralized corporate cron, BTP-native operations, org-level observability. See <a href="./../guide/recipes/external-scheduling-jss.html">Recipes → External scheduling with SAP BTP Job Scheduling Service</a>.</td></tr><tr><td><strong>Manual trigger</strong></td><td>Programmatic <code>run()</code> API and the <code>run</code> OData action.</td><td>Ad-hoc runs, scripts, tests.</td></tr></tbody></table><h2 id="resilience" tabindex="-1">Resilience <a class="header-anchor" href="#resilience" aria-label="Permalink to &quot;Resilience&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Retry with exponential backoff</strong></td><td>All remote I/O is wrapped in a configurable retry policy.</td></tr><tr><td><strong>Concurrency guard</strong></td><td>A pipeline cannot run twice in parallel — a DB-status-based lock rejects the second trigger.</td></tr><tr><td><strong>Transactional batches</strong></td><td>Choose per-batch or full-run transaction scope for replication.</td></tr></tbody></table><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Programmatic API</strong></td><td><code>addPipeline()</code> for dynamic runtime configuration.</td></tr><tr><td><strong>Profile-based overrides</strong></td><td>Different settings per CAP environment profile (<code>[development]</code>, <code>[production]</code>, …) via the native <code>cds.env</code> mechanism.</td></tr><tr><td><strong>Sensible defaults</strong></td><td>Batch size 1000, 10-minute schedule, <code>delta</code> mode for entity-shape reads, <code>full</code> mode for query-shape reads, auto-retry 3×.</td></tr></tbody></table><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Credential isolation</strong></td><td>Each source and target uses its own service credentials via <code>cds.requires</code>, managed by CAP&#39;s native <code>cds.connect.to()</code>.</td></tr></tbody></table><h2 id="pipeline-event-hooks" tabindex="-1">Pipeline event hooks <a class="header-anchor" href="#pipeline-event-hooks" aria-label="Permalink to &quot;Pipeline event hooks&quot;">​</a></h2><p><code>DataPipelineService</code> is a standard <code>cds.Service</code>. Register hooks for every phase via the CAP-native API — full reference with signatures and ordering notes is on the <a href="./management-service.html#event-hooks">Management Service</a> page.</p><table tabindex="0"><thead><tr><th>Event</th><th>Fires</th><th><code>req.data</code></th></tr></thead><tbody><tr><td><code>PIPELINE.START</code></td><td>Once per run, before READ</td><td><code>runId</code>, <code>mode</code>, <code>trigger</code>, <code>config</code>, <code>tracker</code></td></tr><tr><td><code>PIPELINE.READ</code></td><td>Once per run, before batch iteration</td><td><code>runId</code>, <code>config</code>, <code>source</code>, <code>target</code> → handler sets <code>sourceStream</code> (async iterable)</td></tr><tr><td><code>PIPELINE.MAP</code></td><td>Once per batch</td><td><code>runId</code>, <code>batchIndex</code>, <code>sourceRecords</code>, <code>targetRecords</code> (handler fills <code>targetRecords</code>)</td></tr><tr><td><code>PIPELINE.WRITE</code></td><td>Once per batch, after MAP</td><td><code>runId</code>, <code>batchIndex</code>, <code>targetRecords</code> (handler writes and sets <code>statistics</code>)</td></tr><tr><td><code>PIPELINE.DONE</code></td><td>Once per run, success or failure</td><td><code>runId</code>, <code>status</code>, <code>mode</code>, <code>trigger</code>, <code>startTime</code>, <code>endTime</code>, <code>statistics</code>, <code>error?</code></td></tr></tbody></table>',28)])])}const g=t(r,[["render",c]]);export{u as __pageData,g as default};
